/**
 * 模块15：接口令牌桶限流过滤器。
 * 功能：按API Key keyId、Bearer摘要或来源IP实施内存令牌桶限流，超限返回429且不进入业务层。
 * 技术栈：Spring Security OncePerRequestFilter、ConcurrentHashMap和单调时钟。
 */
package com.biz.ontology.common.security;
import com.biz.ontology.api.common.R;import com.biz.ontology.common.exception.PlatformErrorCode;import com.biz.ontology.common.web.RequestIdContext;import com.biz.ontology.config.TrafficControlProperties;import com.fasterxml.jackson.databind.ObjectMapper;import jakarta.servlet.*;import jakarta.servlet.http.*;import org.springframework.http.MediaType;import org.springframework.stereotype.Component;import org.springframework.web.filter.OncePerRequestFilter;import java.io.IOException;import java.nio.charset.StandardCharsets;import java.security.MessageDigest;import java.util.Base64;import java.util.concurrent.*;
@Component public class RateLimitFilter extends OncePerRequestFilter {private final TrafficControlProperties properties;private final ObjectMapper mapper;private final ConcurrentMap<String,Bucket> buckets=new ConcurrentHashMap<>();public RateLimitFilter(TrafficControlProperties p,ObjectMapper m){properties=p;mapper=m;}@Override protected void doFilterInternal(HttpServletRequest request,HttpServletResponse response,FilterChain chain)throws ServletException,IOException{if(!request.getRequestURI().startsWith("/api/v1/")){chain.doFilter(request,response);return;}String key=key(request);boolean login=request.getRequestURI().equals("/api/v1/auth/login");int perMinute=login?properties.getLoginRequestsPerMinute():properties.getRequestsPerMinute();int capacity=login?Math.max(1,Math.min(properties.getBurstCapacity(),perMinute)):properties.getBurstCapacity();Bucket bucket=buckets.computeIfAbsent((login?"login:":"api:")+key,k->new Bucket(capacity,perMinute));if(!bucket.allow()){response.setStatus(429);response.setContentType(MediaType.APPLICATION_JSON_VALUE);mapper.writeValue(response.getOutputStream(),R.error(PlatformErrorCode.AUTH_RATE_LIMITED.getResponseCode(),PlatformErrorCode.AUTH_RATE_LIMITED.getDefaultMessage()));return;}chain.doFilter(request,response);}private String key(HttpServletRequest r){String raw=r.getHeader("X-API-Key");if(raw==null)raw=r.getHeader("Authorization");if(raw==null||raw.isBlank())raw=r.getRemoteAddr();try{byte[] digest=MessageDigest.getInstance("SHA-256").digest(raw.getBytes(StandardCharsets.UTF_8));return Base64.getUrlEncoder().withoutPadding().encodeToString(digest);}catch(Exception e){return raw;}}private static final class Bucket{private final int capacity;private final double refillPerNano;private double tokens;private long last=System.nanoTime();Bucket(int c,int perMinute){capacity=c;tokens=c;refillPerNano=perMinute/(60d*1_000_000_000d);}synchronized boolean allow(){long now=System.nanoTime();tokens=Math.min(capacity,tokens+(now-last)*refillPerNano);last=now;if(tokens<1)return false;tokens-=1;return true;}}}
